EXPECTED_SHA256 = "97e5de08ed8f43f7fd2c196dd943e13bb71278477fcdeaec8e0ad8f1357ac515"

source_bytes = zlib.decompress(base64.b85decode(AGENT_B85))
assert hashlib.sha256(source_bytes).hexdigest() == EXPECTED_SHA256
AGENT_SOURCE = source_bytes.decode("utf-8")
compile(AGENT_SOURCE, "main.py", "exec")
MAIN_PATH = Path.cwd() / "main.py"
MAIN_PATH.write_bytes(source_bytes)

from kaggle_environments.agent import get_last_callable
entry_point = get_last_callable(AGENT_SOURCE)
assert callable(entry_point)
print("main.py", len(source_bytes), "bytes")
print("sha256", EXPECTED_SHA256)
print("resolved entry point", getattr(entry_point, "__name__", type(entry_point).__name__))


OPENING = pd.DataFrame([
    ("five-HIRE parent", 5, 13, 5),
    ("four-HIRE frontier", 4, 26, 4),
    ("three-HIRE ablation", 3, 39, 3),
], columns=["opening", "farm hands hired", "coins after call 0", "hands after call 0"])

fig, ax = plt.subplots(figsize=(12.8, 5.2))
x = np.arange(len(OPENING))
bars = ax.bar(x, OPENING["coins after call 0"], color=["#94a3b8", LEAF, "#d6a56f"], width=.62)
ax.set_xticks(x, OPENING.opening)
ax.set(ylabel="coins remaining", title="Opening liquidity after the first simultaneous call")
for bar, hands in zip(bars, OPENING["farm hands hired"]):
    ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + .8,
            f"{hands} hires", ha="center", va="bottom", fontweight="bold")
sns.despine(); plt.tight_layout(); plt.show()
OPENING


LIVE_CONFIG = {
    "episodeSteps": 720,
    "seed": 20260810,
    "townCenterSellInterval": 24,
    "farmHandCostMult": 1,
}
rows, representative = [], None
for side in (0, 1):
    agents = [str(MAIN_PATH), "starter"] if side == 0 else ["starter", str(MAIN_PATH)]
    env = make("kaggriculture", configuration=LIVE_CONFIG, debug=False)
    env.run(agents)
    final = env.steps[-1]
    assert len(env.steps) == 720
    assert final[side].status == "DONE" and final[1 - side].status == "DONE"
    rows.append({
        "seat": side,
        "candidate bank": float(final[side].reward or 0),
        "starter bank": float(final[1 - side].reward or 0),
        "margin": float(final[side].reward or 0) - float(final[1 - side].reward or 0),
        "steps": len(env.steps),
        "status": final[side].status,
    })
    if side == 0:
        representative = env
live = pd.DataFrame(rows)
assert (live.status == "DONE").all() and (live.margin > 0).all()
live.style.format({"candidate bank": "{:,.0f}", "starter bank": "{:,.0f}", "margin": "{:+,.0f}"})


steps = representative.steps
hours = np.arange(len(steps))
mine = np.asarray([float(s[0].observation.farms[0].money) for s in steps])
theirs = np.asarray([float(s[0].observation.farms[1].money) for s in steps])

fig, ax = plt.subplots(figsize=(14, 5.3))
ax.plot(hours / 24, mine, color=LEAF, lw=2.8, label="four-HIRE frontier")
ax.plot(hours / 24, theirs, color=SOIL, lw=1.8, label="starter")
ax.fill_between(hours / 24, theirs, mine, where=mine >= theirs, color="#ccfbf1", alpha=.55)
ax.set(xlabel="day", ylabel="coins", title="A complete season loaded from main.py")
ax.legend(frameon=False)
sns.despine(); plt.tight_layout(); plt.show()


HOLDOUT = pd.DataFrame([
    ("five-HIRE parent", 314, 66, 0, 0),
    ("four-HIRE frontier", 363, 17, 49, 0),
], columns=["agent", "wins", "non-wins", "loss → win", "win → loss"])

fig, axes = plt.subplots(1, 2, figsize=(15, 5.4), gridspec_kw={"width_ratios": [1.15, 1]})
axes[0].barh(HOLDOUT.agent, HOLDOUT.wins, color=["#94a3b8", LEAF])
axes[0].set(xlabel="wins of 380 paired scenarios", title="Ten-seed paired holdout")
for i, value in enumerate(HOLDOUT.wins):
    axes[0].text(value + 3, i, str(value), va="center", fontweight="bold")

delta = pd.DataFrame([
    ("loss → win", 49), ("win → loss", 0), ("severe harms", 0),
], columns=["outcome", "pairs"])
axes[1].bar(delta.outcome, delta.pairs, color=[GOLD, "#ef4444", NIGHT])
axes[1].set(ylabel="paired scenarios", title="Outcome changes versus parent")
for i, value in enumerate(delta.pairs):
    axes[1].text(i, value + 1, str(value), ha="center", fontweight="bold")
sns.despine(); plt.tight_layout(); plt.show()
HOLDOUT


FRONTIER = pd.DataFrame([
    ("Kaito V26", "exact public policy", 16702.55, 9, 0),
    ("Kaito V25", "exact public policy", 16950.40, 12, 0),
    ("Oleg / Ray C68", "exact public policy", 15803.60, 5, 0),
    ("Pilkwang structured", "exact public policy", 22481.00, 4, 0),
    ("THUNDER current", "open-loop replay tape", 17488.00, 14, 0),
    ("infamem current", "open-loop replay tape", 15347.65, 5, 0),
], columns=["opponent family", "evidence", "mean paired delta", "loss → win", "win → loss"])

fig, ax = plt.subplots(figsize=(13.5, 6.1))
order = FRONTIER.sort_values("mean paired delta")
colors = order.evidence.map({"exact public policy": LEAF, "open-loop replay tape": GOLD})
ax.barh(order["opponent family"], order["mean paired delta"], color=colors)
ax.set(xlabel="mean paired coin delta versus five-HIRE parent",
       title="The opening mattered most against current frontier families")
for i, row in enumerate(order.itertuples(index=False)):
    ax.text(row[2] + 300, i, f"{row[3]} conversions", va="center", fontsize=11)
from matplotlib.patches import Patch
ax.legend(handles=[Patch(color=LEAF, label="exact public policy"),
                   Patch(color=GOLD, label="open-loop replay tape")], frameon=False)
sns.despine(); plt.tight_layout(); plt.show()
FRONTIER


