ax.bar(x - .18, ABLATIONS["win → loss"], .36, color="#ef4444", label="win → loss")
ax.bar(x + .18, ABLATIONS["severe harms"], .36, color=NIGHT, label="paired delta ≤ -5,000")
ax.set_xticks(x, ABLATIONS.candidate, rotation=16, ha="right")
ax.set(ylabel="paired scenarios", title="Every tempting alternative had to survive a harm gate")
ax.legend(frameon=False)
sns.despine(); plt.tight_layout(); plt.show()
